const K=0.1,R=0.15,H=3,S=0.2,MAXS=150,ST=[-2.5,1.5],TOP=2.25;
const L=(x,y)=>0.5*(x*x+4*y*y);
const gn=s=>Math.hypot(s.x,4*s.y);
const cl=v=>Math.max(-H,Math.min(H,v));
const word=s=>Math.abs(s.x)>H||Math.abs(s.y)>H?'diverged':gn(s)<0.001?'converged':s.n>=MAXS?'stopped at 150':s.on?'running':'paused';
const over=s=>{const w=word(s);return w!=='running'&&w!=='paused';};
function adv(s,i){if(over(s))return s;const a=i.learningRate,x=s.x-a*s.x,y=s.y-a*4*s.y;return {...s,x,y,n:s.n+1,path:s.path.concat([[x,y]])};}
const fresh=(x,y,kept)=>({x,y,n:0,on:false,path:[[x,y]],kept});
const keep=s=>s.path.length>1?s.path:s.kept;
export function initialState(){return fresh(ST[0],ST[1],[]);}
export function reduce({state:s,event:e,inputs}){
 if(e.type==='step'){if(!s.on)return s;if(over(s))return {...s,on:false};return e.tick%4?s:adv(s,inputs);}
 if(e.type==='action'){
  if(e.action==='run')return over(s)?s:{...s,on:true};
  if(e.action==='pause')return {...s,on:false};
  if(e.action==='stepOnce')return adv({...s,on:false},inputs);
  if(e.action==='clearTrail')return fresh(s.x,s.y,keep(s));
  if(e.action==='newRun')return fresh(ST[0],ST[1],keep(s));
  return s;}
 if((e.type==='drag_move'||e.type==='drag_end')&&e.node==='ball'){const m=2.9,c=v=>Math.max(-m,Math.min(m,v));return fresh(c(s.x),c(e.value),s.kept);}
 return s;}
const lift=p=>[cl(p[1]),Math.min(K*L(p[0],p[1]),TOP)+0.03,cl(p[0])];
export function evaluate({inputs,state}){
 const s=state||initialState(),w=word(s),g=gn(s),l=L(s.x,s.y);
 let arrow={visible:false};
 if(inputs.showGradientArrow&&w!=='diverged'&&g>=0.001){const dx=-4*s.y/g,dz=-s.x/g,h=Math.SQRT1_2;arrow={visible:true,quaternion:[dz*h,0,-dx*h,h],scale:[1,S*g,1]};}
 return {nodes:{ball:{position:[cl(s.y),Math.min(K*l,TOP)+R,cl(s.x)]},arrow,trail:{points:s.path.map(lift)},ghost:{points:s.kept.map(lift)}},readouts:{loss:l,gradSize:g,steps:s.n,status:w}};}
